// .claude/settings.json: รัน script ก่อน agent ใช้ Edit หรือ Write
{
  "hooks": {
    "PreToolUse": [{
      "matcher": "Edit|Write",
      "hooks": [{ "type": "command",
        "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/protect-files.sh" }]
    }]
  }
}

-- role ของ agent: อ่านได้เฉพาะตารางที่ใช้
GRANT SELECT ON products TO agent_ro;
-- ไม่ให้ INSERT / UPDATE / DELETE และไม่ใช้ account ของ admin

// อันตราย: ต่อ output ของโมเดลเข้า SQL ตรง ๆ
db.query(`SELECT * FROM orders WHERE ${llmFilter}`);
// ปลอดภัยกว่า: ให้โมเดลคืนแค่ค่า ตรวจกับ allowlist แล้วใช้ parameter
if (!ALLOWED_STATUS.includes(llmStatus)) throw new Error('bad status');
db.query('SELECT * FROM orders WHERE status = $1', [llmStatus]);

